        int[][] D = IntStream.range(0, C).mapToObj(i -> IntStream.range(0, C).map(x -> nextInt()).toArray()).toArray(int[][]::new);
        Map<Integer, Map<Integer, Integer>> c = new HashMap<Integer, Map<Integer, Integer>>();
        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= N; j++) {
                int d = (i + j) % 3;
                c.put(d, c.getOrDefault(d, new HashMap<Integer, Integer>()));
                int next = nextInt();
                Map<Integer, Integer> wk = c.get(d);
                wk.put(next, wk.getOrDefault(next, 0) + 1);
            }
        }
        int[][] color = new int[3][C];
        for (int j = 0; j < 3; j++) {
            int[] wk = color[j];
            for (int i = 1; i <= C; i++) {
                int sum = 0;
                Map<Integer, Integer> jColor = c.getOrDefault(j, new HashMap<Integer, Integer>());
                for (Map.Entry<Integer, Integer> e : jColor.entrySet()) {
                    if (e.getKey() == i)
                        continue;
                    sum += D[e.getKey() - 1][i - 1] * e.getValue();
                }
                wk[i - 1] = sum;
            }
        }
        int res = Integer.MAX_VALUE;
        for (int i = 0; i < C; i++) {
            for (int j = 0; j < C; j++) {
                for (int k = 0; k < C; k++) {
                    if (i == j || j == k || k == i)
                        continue;
                    int sum = color[0][i] + color[1][j] + color[2][k];
                    res = Math.min(res, sum);
                }
            }
        }
        out.println(res);
    }

