	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
		}

		long gcd = 0;
		for (int i = 0; i < n; i++) {
			gcd = gcd(gcd, a[i]);
		}

		pr.println(gcd);
	}

	static long gcd(long n, long m) {
		if (m == 0) {
			return n;
		} else {
			return gcd(m, n % m);
		}
	}


	// ---------------------------------------------------
