	public static final int gcd(int a, int b) {
		// a > b にする（swap）
		if (a < b) {
			a = a ^ b;
			b = a ^ b;
			a = a ^ b;
		}

		// ユークリッドの互除法
		int r = -1;
		while (r != 0) {
			r = a % b;
			a = b;
			b = r;
		}

		return a; // b には r=0 の値が入るため、a を返す
	}

	/**
	 * <h1>３つ以上の最大公約数を求める[gcd(a, b, c,...)]</h1>
	 * <p>
