            graph[i][i] = 0;
        }
        int m = edges.length;
        for (int i = 0; i < m; i++) {
            int f = edges[i][0] - 1;
            int t = edges[i][1] - 1;
            long cost = edges[i][2];
            graph[f][t] = cost;
            graph[t][f] = cost;
        }
