			connect[lines[i][0] - 1][lines[i][1] - 1] = true;
			connect[lines[i][1] - 1][lines[i][0] - 1] = true;
		}

		// visitedを初期化
		visited = new boolean[N];
		for (int i = 0; i < N; i++) {
			visited[i] = false;
		}
		int ret = dfs(0, 0);
		System.out.println(ret);
	}

	public static int dfs(int now, int depth) {
		// 訪問済みならこのルートはあり得ないので返却
		if (visited[now]) {
			return 0;
		}
		// 最深部まで探索した場合
		if (depth == N - 1) {
			return 1;
		}
		// 探索済みにする
		visited[now] = true;
