	    }

	    int cs = sc.nexI();

	    int[][] di = new int[cs][cs];
	    sc.nisan(di);

	    int[][] cdefo = new int[h][h];

	    int[][] coleach = new int[cs][3];
	    fill(coleach,0);

	    for(int i=0; i<h; i++){
	        for(int j=0; j<h; j++){
	            cdefo[i][j] = sc.nexI()-1;
	            coleach[cdefo[i][j]][(i+j)%3]++;
	        }
	    }

	    //show2(coleach,"color");

	    int ans =Integer.MAX_VALUE;
	    for(int i=0; i<cs; i++){
	        int sum1 = 0;
	        for(int c=0; c<cs; c++){
	            sum1 += coleach[c][0]*di[c][i];
	        }

	        for(int j=0; j<cs; j++){
	            if(i==j) continue;

	            int sum2=sum1;
    	        for(int c=0; c<cs; c++){
    	            sum2 += coleach[c][1]*di[c][j];
    	        }

	            for(int k=0; k<cs; k++){
	                if(i==k) continue;
