	static class Task {
		static int MAX = 1000000001;

		int N, K;
		int[] W;

		void solve(InputReader in, PrintWriter out) {
			N = in.nextInt();
			K = in.nextInt();
			W = in.nextIntArray(N);

			int ans = Integer.MAX_VALUE;
			int low = 0, high = MAX, mid;
			while (low < high - 1) {
				mid = (low + high) / 2;

				int k = 1;
				int p = mid;
				int cur = 0;

				for (int i = 0; i < N; ++i) {
					if (p < W[i]) {
						k = Integer.MAX_VALUE;
						break;
					}
					cur += W[i];
					if (cur > p) {
						k++;
						cur = W[i];
					}
				}

				if (k > K) {
					low = mid;
				} else {
					high = mid;
					ans = Math.min(ans, p);
				}
			}

			out.println(ans);
		}
	}

