		int truck_count = 0;
		int i = 0;
		while(i < weights.length) {
			if(current_load + weights[i] > q) {
				truck_count++;
				if(truck_count >= k) {
					break;
				}
				current_load = 0;
			}

			current_load += weights[i];
			i++;
		}

