	}


	public static int min_q(int[] weights, int k, int sum, int max_val) {
		int lo = max_val;
		int hi = sum;
		int mid = 0;

		while(lo <= hi) {
			if(hi == lo) {
				return hi;
			}

			mid = (hi + lo) >> 1;
			if(is_possible(weights, mid, k)) {
				hi = mid;
			}else {
				lo = mid+1;
			}
		}

		return mid;


	}


