'''
最大値 : n - k
最小値 : 1
8 1 7 3 9
興味あるのは最大値だけ。
'''

class Allocator(object):

    def __init__(self):
        self.N, self.K = map(int, input().split())
        self.ws = []

        for _ in range(self.N):
            self.ws.append(int(input()))

    def check(self, max_p):
        track, now = 0, 0
        for w in self.ws:
            if w > max_p:
                # wの値がmax_pを超えていた場合は、想定max値が小さすぎるのでFalse
                return False
            elif w + now > max_p:
                # nowの値にwを加えてmax_pを超えた場合は、それ以前までの値までしか積載出来なので、次のトラックを用意する。
                now = w
                track += 1
            else:
                # トラックに積荷をする。
                now += w

        if now > 0:
            # 全ての積荷を行ったのちにまだnowに残っていれば、trackを一つ用意する。
            track += 1

        if int(self.K) < track :
            return False

        return True


amin, amax = 0, int(10E10)
allocate = Allocator()

while amin + 1 != amax:
    amid = (amin + amax) // 2
    if allocate.check(amid):
        amax = amid
    else:
        amin = amid

print(amax)
